from enum import Enum
from typing import Optional

from pydantic import BaseModel


class MetricType(str, Enum):
    Counter = "counter"
    UpDownCounter = "up_down"
    AsyncCounter = "async_counter"
    AsyncUpDownCounter = "async_up_down"
    Gauge = "gauge"
    Histogram = "histogram"


class Metric(BaseModel):
    name: str
    type: MetricType
    unit: Optional[str] = ""
    description: str
